# General f: split into two panels (vertical sep column or horizontal sep row);
# bg = most common color per panel; 3 iff cell in panel A != bg_A AND cell in panel B != bg_B.
def f(g):
    H,W=len(g),len(g[0])
    bg=Counter(x for r in g for x in r).most_common(1)[0][0]
    # try vertical separator first
    s=None
    for c in range(W):
        if len(set(r[c] for r in g))==1 and g[0][c]!=bg:
            s=c; break
    if s is None:
        s=next(r for r in range(H) if len(set(g[r]))==1 and g[r][0]!=bg)
        A=[g[r] for r in range(s)]; B=[g[r] for r in range(s+1,H)]
    else:
        A=[r[:s] for r in g]; B=[r[s+1:] for r in g]
    ba=Counter(x for r in A for x in r).most_common(1)[0][0]
    bb=Counter(x for r in B for x in r).most_common(1)[0][0]
    res=[]
    for ra,rb in zip(A,B):
        res.append([3 if ra[j]!=ba and rb[j]!=bb else 4 for j in range(min(len(ra),len(rb)))])
    return res
